      timer = null;
    const generation = this.lifecycleGeneration,
      account = this.accountKey();
    const finish = (error, value) => {
      if (settled) return;
      settled = true;
      this.cancelTimer(timer);
      this.pendingCalls.delete(finish);
      if (!this.active || generation !== this.lifecycleGeneration) return;
      if (account !== this.accountKey())
        error = new Error("Аккаунт изменился. Откройте NotNFT снова.");
      done(error || null, error ? undefined : value);
    };
    this.pendingCalls.add(finish);
