      "fake_lab_presets_v1",
      "fake_lab_chat_button_v1",
      "fake_lab_native_gifts_v1",
      "fake_lab_local_upgrade_v1",
      "fake_lab_auto_profile_incoming_v1",
      "fake_lab_preset_confirm_v1",
