    const stats = this.cleanStatistics(this.statistics);
    stats.totalGifts = Math.min(Number.MAX_SAFE_INTEGER, stats.totalGifts + 1);
    if (!incoming)
      stats.totalStars = Math.min(
        Number.MAX_SAFE_INTEGER,
        stats.totalStars + price,
      );
    stats.history.unshift({
      id: String(gift.id),
      name: this.giftName(gift),
      price,
      incoming: incoming === true,
      hideName: hideName === true,
      source: source || "menu",
      at: Date.now(),
    });
