    const finish = (error, data) => {
      if (done) return;
      done = true;
      this.cancelTimer(timer);
      if (detached || (this.active && generation === this.lifecycleGeneration))
        callback(error || null, data);
    };
    const receive = (first, second, third) => {
      let error = first;
      let raw = typeof second === "number" ? third : second;
      let status = typeof second === "number" ? second : third;
      // wg.httpPost's real compatibility wrapper calls callback({ok,error,body,status}).
      if (
        second === undefined &&
        third === undefined &&
        first &&
        typeof first === "object" &&
        typeof first.ok === "boolean"
      ) {
        error = first.ok
          ? null
          : first.error || "Whitegram не выполнил HTTP-запрос";
        raw = first.body;
        status = first.status;
      }
      let data;
      try {
        data = typeof raw === "string" ? JSON.parse(raw) : raw;
      } catch (_) {}
      if (data?.error && Number.isFinite(data.status) && data.status >= 400)
        status = data.status;
      if (
        error ||
        (status != null &&
          (!Number.isFinite(status) || status < 200 || status >= 300)) ||
        !data ||
        typeof data !== "object" ||
        data.error
      ) {
        const e = new Error(
          this.errorText(data?.error || error, "Сервис меню не ответил"),
        );
        e.status = status;
        finish(e);
      } else finish(null, data);
    };
    if (!detached)
      timer = this.schedule(
        () => finish(new Error("Истекло время ответа меню")),
        17000,
      );
